(site/'js/main.js').write_text('''"use strict";
const stories = '''+json.dumps(stories)+''';
const toggle = document.querySelector('#menu-toggle');
const panel = document.querySelector('#menu-panel');
if(toggle && panel){
 toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')==='true';toggle.setAttribute('aria-expanded',String(!open));panel.hidden=open;});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!panel.hidden){panel.hidden=true;toggle.setAttribute('aria-expanded','false');toggle.focus();}});
}
function matchingStories(query){ const q=query.trim().toLowerCase(); return q ? stories.map((story,index)=>({story,index})).filter(({story})=>story.slice(0,3).join(' ').toLowerCase().includes(q)) : []; }
function newsletterError(email,count){if(!/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(email.trim()))return 'Enter a valid email address, such as reader@example.test.';if(!count)return 'Choose at least one newsletter.';return '';}
const results=document.querySelector('#results');
if(results){
 const form=document.querySelector('#article-search').form, input=form.querySelector('input');
 const render=()=>{const q=input.value.trim(), matches=matchingStories(q);results.replaceChildren();document.querySelector('#results-title').textContent=q?'Results for “'+q+'”':'Explore our reporting';document.querySelector('#result-status').textContent=!q?'Enter a topic above, such as housing, transit or library.':matches.length?matches.length+' fictional '+(matches.length===1?'story':'stories')+' found.':'Nothing found. Try housing, transit or library.';
 matches.forEach(({story,index})=>{const article=document.createElement('article');article.className='search-result';article.dataset.component='search-result';const h=document.createElement('h3'),a=document.createElement('a'),p=document.createElement('p');a.href='article.html?story='+index;a.textContent=story[0];h.append(a);p.textContent=story[2];article.append(h,p);results.append(article);});};
 input.value=new URLSearchParams(location.search).get('s')||'';render();form.addEventListener('submit',e=>{e.preventDefault();render();document.querySelector('#results-title').setAttribute('tabindex','-1');document.querySelector('#results-title').focus();});
}
const signup=document.querySelector('#newsletter-form');
if(signup)signup.addEventListener('submit',e=>{e.preventDefault();const email=document.querySelector('#email'),lists=[...signup.querySelectorAll('input[name="list"]:checked')], feedback=document.querySelector('#newsletter-feedback'),error=newsletterError(email.value,lists.length);email.setAttribute('aria-invalid',String(Boolean(error&&error.startsWith('Enter'))));feedback.textContent=error||'Demo complete: '+lists.map(x=>x.value).join(', ')+'. No email was sent and no subscription was created.';if(error&&error.startsWith('Enter'))email.focus();else if(error)signup.querySelector('input[name="list"]').focus();else feedback.focus();});
const title=document.querySelector('#article-title');
if(title){const raw=new URLSearchParams(location.search).get('story');const index=raw===null?0:Number(raw);const story=Number.isInteger(index)&&stories[index]?stories[index]:stories[0];title.textContent=story[0];document.title=story[0]+' | Ridgeway News';document.querySelector('#article-region').textContent=story[1];document.querySelector('#article-deck').textContent=story[2];document.querySelector('#article-image').src='assets/'+story[3]+'.svg';}
const share=document.querySelector('#share-story');if(share)share.addEventListener('click',()=>{document.querySelector('#share-status').textContent='Local demo address: '+location.href+' — works only on a device with this site folder.';});
''')
